INSERT INTO "source_passages" VALUES('passage_9735e7db933dca8e2b4a9321','source_version_97a5c2767affe3128350c8e6','video_chapter','1303–1480秒',1303,1480,NULL,'主播称郭寿宝和地方国企参与，提及1.5亿元成本、约8000万元票房、后续合计近4亿元投入，并将演员阵容归于高片酬。演职员身份有公开资料；各投资金额、片酬和动机仍须项目文件，不能说郭寿宝个人承担全部。','ic8_seg_047');
