INSERT INTO "source_passages" VALUES('passage_918ca8098d6b881f70b44ed5','source_version_97a5c2767affe3128350c8e6','video_chapter','1303–1480秒',1303,1480,NULL,'主播称2017年下半年关系出现裂痕，母亲仍安排春晚，其后路征退出公司、官微停更。未核实工商变更日，停更也不能证明已经解除私人关系。','ic8_seg_049');
INSERT INTO "source_passages" VALUES('passage_bbd643cc0369a6e7358e281b','source_version_97a5c2767affe3128350c8e6','video_chapter','1480–1664秒',1480,1664,NULL,'主播把后续作品以网剧为主、缺少顶级院线资源解释为失去照顾，对合作演员等级作贬评。本库把它保存为评论，不据此给演员评级。','ic8_seg_050');
