BEGIN TRANSACTION;
CREATE TABLE appointments (
 id TEXT PRIMARY KEY,
 person_id TEXT NOT NULL REFERENCES people(id),
 start_date TEXT,
 end_date TEXT,
 date_note TEXT NOT NULL,
 region TEXT,
 organization TEXT NOT NULL,
